en:{home:'Home',social:'Social Media',bundles:'Bundles',games:'Games',services:'Services',users:'Users',leaderboard:'Leaderboard',store:'Platform Store',market:'Marketplace',categories:'Categories',why:'Why TOS?',support:'Support',cart:'Cart',login:'Log in',register:'Sign up',live:'Live support',send:'Send →',photo:'Attach photo',subject:'Subject',message:'Write your message...',account:'Account',logout:'Log out',orders:'Orders',settings:'Settings',privacy:'Privacy',links:'Quick links',payments:'Crypto payments'},

