function initLanguage(){
 const actions=document.querySelector('.nav-actions');if(!actions)return;let wrap=$('#languagePicker')||$('.lang');if(!wrap){wrap=document.createElement('div');wrap.className='lang';wrap.id='languagePicker';actions.insertBefore(wrap,actions.firstChild)}
 wrap.innerHTML='<span class="lang-globe" aria-hidden="true">◉</span><select id="languageSelect" aria-label="Dil seç"><option value="tr">🇹🇷 Türkçe</option><option value="en">🇬🇧 English</option></select>';
 const select=$('#languageSelect'),saved=localStorage.getItem('tos_lang'),lang=['tr','en','de'].includes(saved)?saved:'tr';select.value=lang;
 select.onchange=()=>{localStorage.setItem('tos_lang',select.value);applyLanguage(select.value);if(document.body.dataset.page==='auth')window.__authRender?.();};applyLanguage(lang);
 $$('[data-lang]').forEach(b=>b.onclick=()=>{const l=b.dataset.lang;if(!I18N[l])return;localStorage.setItem('tos_lang',l);applyLanguage(l);if($('#languageSelect'))$('#languageSelect').value=l;window.__authRender?.()});
}
function applyLanguage(lang){
 const map=I18N[lang]||I18N.tr;$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(map[k])el.textContent=map[k]});
 $$('#mainNav a').forEach(a=>{const k=a.dataset.i18n;if(k&&map[k])a.textContent=map[k]});
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const source=el.dataset.i18nPlaceholder||el.placeholder;if(!el.dataset.i18nPlaceholder)el.dataset.i18nPlaceholder=source;const x=STATIC_TR[el.dataset.i18nPlaceholder]?.[lang];if(x)el.placeholder=x});
 document.querySelectorAll('body *').forEach(el=>{if(el.children.length||['SCRIPT','STYLE','OPTION','SELECT'].includes(el.tagName))return;const source=el.dataset.tosSource||(el.dataset.tosSource=el.textContent.trim());if(!source)return;const tr=STATIC_TR[source];if(tr?.[lang])el.textContent=tr[lang];else if(lang==='tr'&&tr)el.textContent=source});
 document.documentElement.lang=lang;document.documentElement.dir='ltr';const sel=$('#languageSelect');if(sel)sel.value=lang;
}
let __i18nObserverStarted=false;function startI18nObserver(){if(__i18nObserverStarted||!document.body)return;__i18nObserverStarted=true;let busy=false;new MutationObserver(()=>{if(busy)return;busy=true;requestAnimationFrame(()=>{busy=false;applyLanguage(localStorage.getItem('tos_lang')||'tr')})}).observe(document.body,{childList:true,subtree:true});}
function initAuth(){
 const qs=new URLSearchParams(location.search);let mode=qs.get('mode')==='register'?'register':'login';
 const refs={login:$('#authLoginTab'),register:$('#authRegisterTab'),identifier:$('#authIdentifier'),email:$('#authEmail'),confirm:$('#authConfirm'),pass:$('#authPass'),error:$('#authError'),title:$('#authTitle'),hint:$('#authHint'),submit:$('#authSubmit'),emailField:$('#emailField'),confirmField:$('#confirmField'),label:document.querySelector('[data-auth-label]'),toggle:$('#togglePassword'),form:$('#authForm')};
 if(!refs.form)return;
 const copy={tr:{login:{title:'Giriş yap',hint:'Nickname veya e-posta adresinle hesabına giriş yap.',submit:'Giriş yap →',label:'Nickname veya e-posta',ph:'kullanici_adi veya mail@example.com'},register:{title:'Hesap oluştur',hint:'Nickname, e-posta ve şifrenle hesabını oluştur.',submit:'Hesap oluştur →',label:'Nickname',ph:'kullanici_adi'}},en:{login:{title:'Log in',hint:'Log in with your nickname or email.',submit:'Log in →',label:'Nickname or email',ph:'username or mail@example.com'},register:{title:'Create account',hint:'Create your account with a nickname, email and password.',submit:'Create account →',label:'Nickname',ph:'username'}}};
 const render=()=>{const reg=mode==='register',L=localStorage.getItem('tos_lang')||'tr',c=(copy[L]||copy.tr)[reg?'register':'login'];refs.label.textContent=c.label;refs.title.textContent=c.title;refs.hint.textContent=c.hint;refs.submit.textContent=c.submit;refs.identifier.placeholder=c.ph;refs.emailField.classList.toggle('hidden',!reg);refs.confirmField.classList.toggle('hidden',!reg);refs.login?.classList.toggle('active',!reg);refs.register?.classList.toggle('active',reg);refs.identifier.name=reg?'nickname':'identifier';refs.email.required=reg;refs.confirm.required=reg;refs.pass.autocomplete=reg?'new-password':'current-password';};
 refs.login?.addEventListener('click',()=>{mode='login';history.replaceState(null,'','/auth.html');render()});refs.register?.addEventListener('click',()=>{mode='register';history.replaceState(null,'','/auth.html?mode=register');render()});
 refs.pass?.addEventListener('input',()=>{const v=refs.pass.value,bar=$('#passwordStrengthBar'),label=$('#passwordStrength');if(!bar||!label)return;let score=0;if(v.length>=8)score++;if(v.length>=12)score++;if(/[A-Z]/.test(v))score++;if(/[0-9]/.test(v))score++;if(/[^A-Za-z0-9]/.test(v))score++;bar.style.width=`${Math.min(100,score*20)}%`;label.textContent=v?(['Çok zayıf','Zayıf','Orta','İyi','Güçlü','Çok güçlü'][score]||''):'Güçlü şifre oluştur'});
 refs.toggle?.addEventListener('click',()=>{const visible=refs.pass.type==='text';refs.pass.type=visible?'password':'text';refs.toggle.textContent=visible?'Göster':'Gizle'});
 refs.form.addEventListener('submit',async e=>{e.preventDefault();const reg=mode==='register',identifier=refs.identifier.value.trim(),password=refs.pass.value;if(!identifier||!password||(reg&&(!refs.email.value.trim()||!refs.confirm.value))){refs.error.textContent='Lütfen gerekli alanları doldur.';refs.error.classList.remove('hidden');return}if(reg&&password!==refs.confirm.value){refs.error.textContent='Şifreler eşleşmiyor.';refs.error.classList.remove('hidden');return}refs.submit.disabled=true;refs.error.classList.add('hidden');try{await api('/api/users/'+(reg?'register':'login'),{method:'POST',body:JSON.stringify(reg?{nickname:identifier,email:refs.email.value.trim(),password,confirm_password:refs.confirm.value}:{identifier,password})});location.replace(qs.get('next')||'/profile.html')}catch(x){refs.error.textContent=x.message||'İşlem başarısız.';refs.error.classList.remove('hidden');refs.submit.disabled=false}});
 render();
}
const SOCIAL_ICON={instagram:'instagram',youtube:'youtube',facebook:'facebook',discord:'discord',tiktok:'tiktok',twitter:'twitter',snapchat:'snapchat',telegram:'telegram'};
function socialIcon(platform){const file=SOCIAL_ICON[platform]||platform;return `<img src="/assets/social/${file}.svg" alt="" loading="lazy">`}
function freshMediaUrl(url){if(!url)return url;const sep=url.includes('?')?'&':'?';return url+sep+'cb='+Date.now()}
function renderSocialLinks(items,targetId='profileSocials'){const box=$('#'+targetId);if(!box)return;const labels={instagram:'Instagram',youtube:'YouTube',facebook:'Facebook',discord:'Discord',tiktok:'TikTok',twitter:'Twitter / X',snapchat:'Snapchat',telegram:'Telegram'};if(!items?.length){box.innerHTML='<div class="empty-card">Sosyal bağlantı eklenmemiş.</div>';return}box.innerHTML=items.map(x=>`<a class="profile-social-link social-${esc(x.platform)}" href="${esc(x.url)}" target="_blank" rel="noopener"><span>${socialIcon(x.platform)}</span><div><b>${esc(labels[x.platform]||x.platform)}</b><small>Profili aç ↗</small></div></a>`).join('')}
function renderCover(targetId,url){const box=$('#'+targetId);if(!box)return;box.innerHTML='';if(!url)return;const isVideo=/[?&]media=video(?:&|$)/i.test(url);if(isVideo){const v=document.createElement('video');v.src=freshMediaUrl(url);v.autoplay=true;v.loop=true;v.muted=true;v.playsInline=true;v.preload='auto';box.appendChild(v)}else{const img=document.createElement('img');img.src=freshMediaUrl(url);img.alt='';img.loading='eager';box.appendChild(img)}}

async function initProfile(){
 const u=await requireUser(); if(!u)return;
 $('#profileName').textContent=u.display_name||u.nickname;$('#profileNick').textContent='@'+u.nickname;$('#profileEmail').textContent=u.email||'';$('#profileId').textContent='#'+u.id;$('#dataId').textContent='#'+u.id;
 $('#profileSince').textContent=new Date(u.created_at).toLocaleDateString('tr-TR');$('#avatarText').textContent=(u.display_name||u.nickname||'T').slice(0,1).toUpperCase();
 if(u.avatar_url){$('#avatarImage').src=freshMediaUrl(u.avatar_url);$('#avatarImage').classList.remove('hidden');$('#avatarText').classList.add('hidden')}renderCover('profileCoverMedia',u.cover_url);
 $('#dataNick').textContent=u.nickname;$('#dataName').textContent=u.display_name||u.nickname;$('#dataEmail').textContent=u.email||'—';$('#profileBio').textContent=u.bio||'Profil açıklamanı Ayarlar bölümünden ekleyebilirsin.';
 $('#publicTitle').textContent='@'+u.nickname;$('#publicProfileLink').href='/user.html?nickname='+encodeURIComponent(u.nickname);$('#dataPrivacy').textContent=u.profile_public===false?'Gizli':'Herkese açık';renderSocialLinks(u.socials||[]);
 $('#logoutUser')?.addEventListener('click',async()=>{await api('/api/users/logout',{method:'POST'}).catch(()=>{});location.replace('/');});
 try{const d=await api('/api/orders/mine/list');const box=$('#myOrders');box.innerHTML=d.orders.length?d.orders.slice(0,5).map(o=>`<a class="order-row" href="/orders.html"><span>#${o.id}</span><strong>${money(o.total)}</strong><small>${esc(o.status)}</small></a>`).join(''):'<div class="empty-card">Henüz siparişin yok.</div>';}catch{if($('#myOrders'))$('#myOrders').innerHTML='<div class="empty-card">Siparişler yüklenemedi.</div>'}
}
async function initOrders(){
 const u=await requireUser(); if(!u)return;
 const box=$('#ordersPageList');if(!box)return;
 try{const d=await api('/api/orders/mine/list');box.innerHTML=d.orders.length?d.orders.map(o=>`<a class="order-row order-row-large" href="/orders.html"><div><b>#${o.id}</b><small>${new Date(o.created_at).toLocaleString('tr-TR')}</small></div><strong>${money(o.total)}</strong><span class="status-chip">${esc(o.status)}</span></a>`).join(''):'<div class="empty-card">Henüz siparişin yok. <a href="/market.html">Market’e git →</a></div>';}catch{box.innerHTML='<div class="empty-card">Siparişler yüklenemedi.</div>'}
}
function socialSettingsMarkup(items){const labels={instagram:['Instagram','https://instagram.com/'],youtube:['YouTube','https://youtube.com/@'],facebook:['Facebook','https://facebook.com/'],discord:['Discord','https://discord.com/users/'],tiktok:['TikTok','https://tiktok.com/@'],twitter:['Twitter / X','https://x.com/'],snapchat:['Snapchat','https://snapchat.com/add/'],telegram:['Telegram','https://t.me/']};const map=new Map((items||[]).map(x=>[x.platform,x.url]));return Object.entries(labels).map(([k,v])=>`<label class="social-input-row social-${k}"><span class="social-input-icon">${socialIcon(k)}</span><span><b>${v[0]}</b><input class="input" data-social="${k}" value="${esc(map.get(k)||'')}" placeholder="${v[1]}kullanici"></span></label>`).join('')}
async function initSettings(){
 const u=await requireUser(); if(!u)return;
 $('#settingsDisplayName').value=u.display_name||u.nickname;$('#settingsBio').value=u.bio||'';
 const txt=u.avatar_url;renderCover('settingsCoverPreview',u.cover_url);$('#settingsAvatarText').textContent=(u.display_name||u.nickname||'T').slice(0,1).toUpperCase();if(txt){$('#settingsAvatarPreview').src=freshMediaUrl(txt);$('#settingsAvatarPreview').classList.remove('hidden');$('#settingsAvatarText').classList.add('hidden')}
 try{const d=await api('/api/users/preferences');$('#profilePublic').checked=d.preferences?.profile_public!==false}catch{$('#profilePublic').checked=true}
 const socials=u.socials||[];$('#socialForm').innerHTML=socialSettingsMarkup(socials);
 $('#settingsAvatar')?.addEventListener('change',()=>{const f=$('#settingsAvatar').files?.[0];if(!f)return;if(f.size>2*1024*1024){toast('Fotoğraf en fazla 2 MB olabilir.');$('#settingsAvatar').value='';return}const r=new FileReader();r.onload=()=>{$('#settingsAvatarPreview').src=r.result;$('#settingsAvatarPreview').classList.remove('hidden');$('#settingsAvatarText').classList.add('hidden')};r.readAsDataURL(f)});
 $('#removeAvatar')?.addEventListener('click',async()=>{try{await api('/api/users/avatar',{method:'DELETE'});$('#settingsAvatar').value='';$('#settingsAvatarPreview').classList.add('hidden');$('#settingsAvatarText').classList.remove('hidden');toast('Profil fotoğrafı kaldırıldı ✓')}catch(x){toast(x.message)}});
 $('#settingsCover')?.addEventListener('change',()=>{const f=$('#settingsCover').files?.[0];if(!f)return;if(f.size>15*1024*1024){toast('Arka plan en fazla 15 MB olabilir.');$('#settingsCover').value='';return}const r=new FileReader();if(f.type.startsWith('video/')){const v=document.createElement('video');v.controls=true;v.muted=true;v.src=URL.createObjectURL(f);$('#settingsCoverPreview').replaceChildren(v)}else{r.onload=()=>{const img=document.createElement('img');img.src=r.result;$('#settingsCoverPreview').replaceChildren(img)};r.readAsDataURL(f)}});
 $('#removeCover')?.addEventListener('click',async()=>{try{await api('/api/users/cover',{method:'DELETE'});$('#settingsCover').value='';$('#settingsCoverPreview').innerHTML='';toast('Arka plan kaldırıldı ✓')}catch(x){toast(x.message)}});
 $('#settingsProfileForm')?.addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const fd=new FormData();fd.append('display_name',$('#settingsDisplayName').value.trim());fd.append('bio',$('#settingsBio').value.trim());const f=$('#settingsAvatar')?.files?.[0];if(f)fd.append('avatar',f);await api('/api/users/profile',{method:'PUT',body:fd});const cf=$('#settingsCover')?.files?.[0];if(cf){const cfd=new FormData();cfd.append('cover',cf);await api('/api/users/cover',{method:'POST',body:cfd});}toast('Profil güncellendi ✓');setTimeout(()=>location.href='/profile.html',450)}catch(x){toast(x.message)}finally{btn.disabled=false}});
 $('#saveSocials')?.addEventListener('click',async()=>{const socials=$$('#socialForm [data-social]').map(i=>({platform:i.dataset.social,url:i.value.trim()})).filter(x=>x.url);try{await api('/api/users/socials',{method:'PUT',body:JSON.stringify({socials})});toast('Sosyal bağlantılar kaydedildi ✓');setTimeout(()=>location.href='/profile.html',450)}catch(x){toast(x.message)}});
 $('#passwordForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/users/password',{method:'POST',body:JSON.stringify({current_password:$('#currentPassword').value,new_password:$('#newPassword').value,confirm_password:$('#confirmPassword').value})});e.target.reset();toast('Şifre güncellendi ✓')}catch(x){toast(x.message)}});
 $('#savePrivacy')?.addEventListener('click',async()=>{try{await api('/api/users/preferences',{method:'PUT',body:JSON.stringify({profile_public:$('#profilePublic').checked})});toast('Gizlilik tercihi kaydedildi ✓')}catch(x){toast(x.message)}});
}
async function initPublicProfile(){
 const params=new URLSearchParams(location.search),nick=params.get('nickname');const id=params.get('id');if(!nick&&!id)return;
 try{const d=await api(nick?'/api/users/profile/'+encodeURIComponent(nick):'/api/users/id/'+encodeURIComponent(id)),p=d.profile;$('#publicName').textContent=p.display_name||p.nickname;$('#publicNick').textContent='@'+p.nickname;$('#publicBio').textContent=p.bio||'TOS MARKET kullanıcısı';$('#publicId').textContent='#'+p.id;renderCover('publicCoverMedia',p.cover_url);$('#publicSince').textContent=new Date(p.created_at).toLocaleDateString('tr-TR');if(p.avatar_url){$('#publicAvatar').src=freshMediaUrl(p.avatar_url);$('#publicAvatar').classList.remove('hidden');$('#publicAvatarText').classList.add('hidden')}renderSocialLinks(p.socials||[],'publicSocials')}catch{const box=$('#publicProfileRoot');if(box)box.innerHTML='<div class="empty-card">Profil bulunamadı veya gizli.</div>'}
}

async function initUsers(){
 const box=$('#usersGrid'); if(!box)return; let timer;
 const renderUsers=(items)=>{box.innerHTML=items.length?items.map(u=>{const av=u.avatar_url?`<img src="${esc(freshMediaUrl(u.avatar_url))}" alt="">`:`<span>${esc((u.display_name||u.nickname||'T').slice(0,1).toUpperCase())}</span>`;return `<a class="user-directory-card" href="/user.html?id=${encodeURIComponent(u.id)}"><div class="directory-avatar">${av}</div><div class="directory-copy"><b>${esc(u.display_name||u.nickname)}</b><small>@${esc(u.nickname)} · #${u.id}</small><span>${esc(u.bio||'TOS MARKET community profile')}</span></div><em>${u.has_cover?'MEDIA':''}</em></a>`}).join(''):'<div class="empty-card">Kullanıcı bulunamadı.</div>';};
 const load=async()=>{box.innerHTML='<div class="loading-card">Kullanıcılar yükleniyor…</div>';try{const q=$('#userSearch')?.value.trim()||'';const d=await api('/api/users/public/list?'+new URLSearchParams({q}));renderUsers(d.users||[]);const lb=$('#leaderboardList');if(lb){const ranked=[...(d.users||[])].sort((a,b)=>(Number(b.id)||0)-(Number(a.id)||0)).slice(0,8);lb.innerHTML=ranked.length?ranked.map((u,i)=>`<a class="leader-row" href="/user.html?id=${u.id}"><strong>#${i+1}</strong><div><b>${esc(u.display_name||u.nickname)}</b><small>@${esc(u.nickname)} · Profile #${u.id}</small></div><span>${u.has_cover?'Media profile':'Community profile'}</span></a>`).join(''):'<div class="empty-card">Kullanıcı bulunamadı.</div>';}}catch(e){box.innerHTML='<div class="empty-card">Kullanıcılar yüklenemedi.</div>'}};
 $('#userSearch')?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,220)});await load();
}

function boot(){
 applyTheme();initLanguage();startI18nObserver();nav();updateCount();initSupport();initAssistant();
 const p=document.body.dataset.page;
 if(p==='home')initHome();if(p==='cart')renderCart();if(p==='product')initProduct();if(p==='checkout')initCheckout();if(p==='payment')initPayment();if(p==='order')initOrder();if(p==='auth')initAuth();if(p==='profile')initProfile();if(p==='orders')initOrders();if(p==='settings')initSettings();if(p==='public-profile')initPublicProfile();if(p==='users')initUsers();
}
boot();
